	title 'QD Slab Patch        GS ROM 2 Patch'******************************************************************	  Slab Patch for Rom2*** Contents:** IntallSlabPatches*** Change History** 09 May 87	Steven Glass** First added to patch for system disk 2.0** 05 Dec 88	Steven Glass** Removed patch from file and just installed patch that* is linked from rom source.** 08 Dec 88	Steven Glass** Patched additional routines.**********************************************************************************************************************************			   **              Copyright (C) 1985-1988		   **              All Rights Reserved		   **              Apple Computer, Inc.		   **			   *****************************************************************	include 'all.macros'	INCLUDE ':::qd:QDEquates:core.globals1'	INCLUDE ':::qd:QDEquates:core.globals2'	INCLUDE ':::qd:QDEquates:region.equs'	INCLUDE ':::qd:QDEquates:rect.equs'	INCLUDE ':::qd:QDEquates:slab.equs'	INCLUDE ':::qd:QDEquates:conics.equs'	INCLUDE ':::qd:QDEquates:qd.data.asm'****************************************************************** StdRgn** Common region routine that is central	point for* all region drawing routines.** When control gets	here, all inputs are on zero page.*       TheRgn is kept at RgnC and is already locked and*              dereferenced.*       ThePat (if any) is in FillPat*       WhatToDo is	in DrawVerb*** External Refs:	import CommonSlabSetup** Entry Points:*	none*	longa on	; mode	longi on** Change History** 11 Dec 88	Steven Glass** This is part of the patch because it is the only way to* get at the routine DrawRgn.  DrawRgn is called by* CommonSlabSetup.  Neither routine is vectored.** DrawRgn needs to be patched so that it will call* the new routines that set up the pattern and mask slices* so the new slab routines can be used.*****************************************************************iStdRgn	PROC EXPORT	lda DrawVerb	bne UseNewCode	jml $FE42A1UseNewCode	lda #RgnNoun	sta DrawNoun	; put on zp too!!!	jsl PutPictStuff	; inputs on zp and in a-reg	bcc NoPicErr	rtl	; return the errorNoPicErr	jmp CommonSlabSetup	ENDP	END